"use client";

import { useRouter, useParams } from "next/navigation";
import { useQuery, useMutation } from "@tanstack/react-query";
import axiosInstance from "@/utils/axiosInstance";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import { useState, useEffect } from "react";
import { toast } from "react-toastify";
import Select from "react-select";

interface Category {
  categoryId: number;
  categoryName: string;
}

interface Product {
  productName: string;
  detail: string;
  price: number;
  weight: number;
  productCategory?: { categoryId: number };
}

interface UpdateProductValues {
  productName: string;
  detail: string;
  price: number;
  weight: number;
  categoryId: number;
}

const fetchProduct = async (productId: string): Promise<Product> => {
  const response = await axiosInstance.get(`/products/${productId}`);
  return response.data;
};

const fetchCategories = async (): Promise<Category[]> => {
  const response = await axiosInstance.get("/categories");
  return response.data.data.content;
};

const updateProduct = async ({ productId, values }: { productId: string; values: UpdateProductValues }) => {
  const response = await axiosInstance.patch(`/products/update/${productId}`, values);
  return response.data;
};

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams() as { productId: string };
  const [initialValues, setInitialValues] = useState<UpdateProductValues>({
    productName: "",
    detail: "",
    price: 0,
    weight: 0,
    categoryId: 0,
  });

  const { data: product, isLoading: isProductLoading } = useQuery<Product>({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const { data: categories, isLoading: isCategoriesLoading } = useQuery<Category[]>({
    queryKey: ["categories"],
    queryFn: fetchCategories,
  });

  useEffect(() => {
    if (product) {
      setInitialValues({
        productName: product.productName || "",
        detail: product.detail || "",
        price: product.price || 0,
        weight: product.weight || 0,
        categoryId: product.productCategory?.categoryId || 0,
      });
    }
  }, [product]);

  const mutation = useMutation({
    mutationFn: (values: UpdateProductValues) => updateProduct({ productId, values }),
    onSuccess: () => {
      toast.success("Product updated successfully!");
    },
    onError: (error) => {
      toast.error("Failed to update product.");
      console.error(error);
    },
  });

  if (isProductLoading || isCategoriesLoading) return <div>Loading...</div>;

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <h2 className="text-3xl font-semibold mb-4">Edit Product Draft</h2>
      {initialValues.productName ? (
        <Formik
          enableReinitialize
          initialValues={initialValues}
          validationSchema={Yup.object({
            productName: Yup.string().min(3, "Product name must be at least 3 characters long").required("Required"),
            detail: Yup.string().min(3, "Details must be at least 3 characters long").required("Required"),
            price: Yup.number().positive("Price must be a positive number").required("Required"),
            weight: Yup.number().positive("Weight must be a positive number").required("Required"),
            categoryId: Yup.number().required("Category is required"),
          })}
          onSubmit={(values) => {
            mutation.mutate(values);
          }}
        >
          {({ values, setFieldValue, isSubmitting }) => (
            <Form className="space-y-4">
              <div>
                <label className="block text-gray-500">Product Name</label>
                <Field type="text" name="productName" className="border p-2 rounded w-full" />
                <ErrorMessage name="productName" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Details</label>
                <Field type="text" name="detail" className="border p-2 rounded w-full" />
                <ErrorMessage name="detail" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Price (Rp.)</label>
                <Field type="number" name="price" className="border p-2 rounded w-full" />
                <ErrorMessage name="price" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Weight</label>
                <Field type="number" name="weight" className="border p-2 rounded w-full" />
                <ErrorMessage name="weight" component="div" className="text-red-500" />
              </div>

              <div>
                <label className="block text-gray-500">Product Category</label>
                <Select
                  options={categories?.map((category) => ({
                    value: category.categoryId,
                    label: category.categoryName,
                  }))}
                  value={categories?.find((cat) => cat.categoryId === values.categoryId) || null}
                  onChange={(selectedOption) => {
                    setFieldValue("categoryId", selectedOption?.value || 0);
                  }}
                  className="border p-2 rounded w-full text-gray-500"
                  placeholder="Search category..."
                />
                <ErrorMessage name="categoryId" component="div" className="text-red-500" />
              </div>

              <button type="submit" className="bg-blue-500 text-white px-4 py-2 rounded disabled:bg-gray-400" disabled={isSubmitting || mutation.isLoading}>
                {mutation.isLoading ? "Updating..." : "Update Product"}
              </button>
            </Form>
          )}
        </Formik>
      ) : (
        <div>Loading product details...</div>
      )}
    </div>
  );
};

export default EditDraftProduct;